package com.example.meetomxh;

import android.content.Intent;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.content.ContextCompat;
import androidx.recyclerview.widget.GridLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import com.bumptech.glide.Glide;
import com.example.meetomxh.supabase.*;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;

/** Private, cursor-paged conversation media browser. Asset references are signed at read time by Glide's loader. */
public final class SharedMediaGalleryActivity extends AppCompatActivity {
    public static final String EXTRA_CHAT_ID="chat_id";
    private final List<JSONObject> rows=new ArrayList<>();private GalleryAdapter adapter;private String chatId,kind="all";private long beforeSeq=Long.MAX_VALUE;private int beforePosition=-1;private boolean loading,hasMore=true;private TextView status;private ProgressBar progress;private RecyclerView list;
    @Override protected void onCreate(Bundle s){super.onCreate(s);chatId=getIntent().getStringExtra(EXTRA_CHAT_ID);if(chatId==null){finish();return;}build();load(true);}
    private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(ContextCompat.getColor(this,R.color.app_bg));LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(10),dp(8),dp(10),dp(8));TextView back=new TextView(this);back.setText("‹");back.setTextSize(32);header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));back.setOnClickListener(v->finish());TextView title=new TextView(this);title.setText("Shared media");title.setTextSize(18);title.setTextColor(ContextCompat.getColor(this,R.color.text_primary));header.addView(title);root.addView(header);
        LinearLayout tabs=new LinearLayout(this);tabs.setGravity(Gravity.CENTER);for(String[] t:new String[][]{{"all","All"},{"image","Photos"},{"video","Videos"}}){Button b=new Button(this);b.setText(t[1]);b.setAllCaps(false);tabs.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));b.setOnClickListener(v->{if(!kind.equals(t[0])){if(!loading){kind=t[0];load(true);}}});}root.addView(tabs);
        progress=new ProgressBar(this);root.addView(progress,new LinearLayout.LayoutParams(dp(32),dp(32)));status=new TextView(this);status.setGravity(Gravity.CENTER);status.setTextColor(ContextCompat.getColor(this,R.color.text_secondary));root.addView(status,new LinearLayout.LayoutParams(-1,dp(48)));
        list=new RecyclerView(this);GridLayoutManager lm=new GridLayoutManager(this,3);list.setLayoutManager(lm);adapter=new GalleryAdapter();list.setAdapter(adapter);list.addOnScrollListener(new RecyclerView.OnScrollListener(){@Override public void onScrolled(RecyclerView r,int dx,int dy){if(dy>0&&lm.findLastVisibleItemPosition()>=adapter.getItemCount()-6)load(false);}});root.addView(list,new LinearLayout.LayoutParams(-1,0,1));status.setOnClickListener(v->load(rows.isEmpty()));setContentView(root);}
    private void load(boolean reset){if(loading)return;if(reset){rows.clear();beforeSeq=Long.MAX_VALUE;beforePosition=-1;hasMore=true;adapter.notifyDataSetChanged();}if(!hasMore){status.setText(rows.isEmpty()?"No shared media yet":"You’re all caught up");return;}loading=true;progress.setVisibility(View.VISIBLE);Api.run(()->RpcClient.object("get_shared_media",Api.obj("p_conversation_id",chatId,"p_kind",kind,"p_before_seq",beforeSeq==Long.MAX_VALUE?null:beforeSeq,"p_before_position",beforeSeq==Long.MAX_VALUE?null:beforePosition,"p_limit",30)),new Api.Callback<JSONObject>(){public void success(JSONObject result){loading=false;progress.setVisibility(View.GONE);JSONArray page=result.optJSONArray("items");if(page==null)page=new JSONArray();for(int i=0;i<page.length();i++){JSONObject item=page.optJSONObject(i);if(item!=null)rows.add(item);}hasMore=page.length()==30;if(page.length()>0)beforeSeq=page.optJSONObject(page.length()-1).optLong("seq");beforePosition=page.optJSONObject(page.length()-1).optInt("position");adapter.notifyDataSetChanged();status.setText(rows.isEmpty()?"No shared photos or videos yet":"");}public void error(String e){loading=false;progress.setVisibility(View.GONE);status.setText(e+" · Tap to retry");}});}
    private final class GalleryAdapter extends RecyclerView.Adapter<GalleryHolder>{public GalleryHolder onCreateViewHolder(ViewGroup p,int t){FrameLayout f=new FrameLayout(SharedMediaGalleryActivity.this);ImageView image=new ImageView(SharedMediaGalleryActivity.this);image.setId(android.R.id.icon);image.setScaleType(ImageView.ScaleType.CENTER_CROP);f.addView(image,new FrameLayout.LayoutParams(-1,-1));TextView badge=new TextView(SharedMediaGalleryActivity.this);badge.setId(android.R.id.text1);badge.setText("▶");badge.setTextColor(-1);badge.setTextSize(22);badge.setGravity(Gravity.CENTER);FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(-1,-1);f.addView(badge,bp);f.setLayoutParams(new RecyclerView.LayoutParams(-1,dp(112)));return new GalleryHolder(f,image,badge);}public void onBindViewHolder(GalleryHolder h,int p){JSONObject row=rows.get(p);String ref=Dto.asset(row.optString("asset_id"));boolean video="video".equals(row.optString("kind"));h.badge.setVisibility(video?View.VISIBLE:View.GONE);if(video){h.image.setImageResource(R.drawable.ic_memories);Api.run(()->com.example.meetomxh.storage.SupabaseStorage.videoThumbnail(ref),new Api.Callback<android.graphics.Bitmap>(){public void success(android.graphics.Bitmap b){if(b!=null&&ref.equals(h.image.getTag()))h.image.setImageBitmap(b);}public void error(String e){}});h.image.setTag(ref);}else Glide.with(h.image).load(ref).centerCrop().placeholder(R.drawable.avatar_neutral).error(R.drawable.ic_media_error).into(h.image);h.itemView.setContentDescription(video?"Shared video":"Shared photo");h.itemView.setOnClickListener(v->{if(video)startActivity(new Intent(SharedMediaGalleryActivity.this,VideoPlayerActivity.class).putExtra(VideoPlayerActivity.EXTRA_ASSET,ref));else{java.util.ArrayList<String> images=new java.util.ArrayList<>();int start=0;for(JSONObject item:rows)if("image".equals(item.optString("kind"))){if(item==row)start=images.size();images.add(Dto.asset(item.optString("asset_id")));}startActivity(new Intent(SharedMediaGalleryActivity.this,ChatImageViewerActivity.class).putExtra(ChatImageViewerActivity.EXTRA_IMAGE_URLS,images.toArray(new String[0])).putExtra(ChatImageViewerActivity.EXTRA_START_INDEX,start));}});}public int getItemCount(){return rows.size();}}
    private static final class GalleryHolder extends RecyclerView.ViewHolder{final ImageView image;final TextView badge;GalleryHolder(View v,ImageView i,TextView b){super(v);image=i;badge=b;}}
    private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
}
